import os,json
parents=['/System/Cryptexes','/System/Volumes/Preboot/Cryptexes']
roots=[]
for parent in parents:
    try:
        with os.scandir(parent) as children:
            roots.extend(sorted(child.path for child in children if child.is_dir()))
    except FileNotFoundError:pass
remote='/System/Library/PrivateFrameworks/RemoteProcessingBlock.framework'
audio='/System/Library/PrivateFrameworks/AudioDSPGraph.framework'
result=[]
for name in (remote,remote+'/Versions/A/RemoteProcessingBlock',audio,audio+'/Versions/A/AudioDSPGraph'):
    for prefix in ['',*roots]:
        path=prefix+name
        try:
            info=os.lstat(path);entry={'path':path,'exists':True,'mode':info.st_mode}
        except (FileNotFoundError,NotADirectoryError):entry={'path':path,'exists':False}
        result.append(entry)
        assert not (name.startswith(remote) and entry['exists']), 'RemoteProcessingBlock entry exists: '+path
print(json.dumps({'overlay_roots':roots,'entries':result},sort_keys=True))
